"""
    This function remove space

    Parameters :
        string: the string
    Returns :
        return string witout space
    """
def remove_whitespace(string: Any) -> object {
    return string.replace(' ', '');
}

test_blocks:
test "t0" {
    assert (remove_whitespace('') == '');;
}

test "t1" {
    assert (remove_whitespace('    ') == '');;
}

test "t2" {
    assert (remove_whitespace('abc  ') == 'abc');;
}

test "t3" {
    assert (remove_whitespace('abc  def') == 'abcdef');;
}

test "t4" {
    assert (remove_whitespace(remove_whitespace('hello   world')) == 'helloworld');;
}

test "t5" {
    assert (remove_whitespace(remove_whitespace("Hello World!")) == "HelloWorld!");;
}

test "t6" {
    assert (remove_whitespace("This    is a string.") == "Thisisastring.");;
}

